#!/bin/bash
# Generated by scripts/export-killercoda.ts. Passes (exit 0) when the named checks of lab-m07-shelf-pod pass.
# Environment overrides, for local tests: SHELF_BIN, KUBECONFIG, SHELF_MARKER_DIR, SHELF_COURSE_DIR, SHELF_LABS_DIR.
LAB=lab-m07-shelf-pod
CHECKS="pod-ready runs-the-api native-sidecar log-shipped"
MARK="${SHELF_MARKER_DIR:-/tmp}"
SHELF="${SHELF_BIN:-/usr/local/bin/shelf}"
[ -f "$MARK/shelf-failed" ] && { echo "Setup failed: $(cat "$MARK/shelf-failed"). See /tmp/shelf-setup.log." >&2; exit 1; }
[ -f "$MARK/shelf-ready" ] || { echo "Setup is not finished. Wait for RESULT: ready in the first terminal, then click Check again." >&2; exit 1; }
export KUBECONFIG="${KUBECONFIG:-/root/.kube/config}"
cd "${SHELF_COURSE_DIR:-/root/course}" || { echo "The course folder is missing." >&2; exit 1; }
kubectl --context kind-reconcile --request-timeout=10s get nodes >/dev/null 2>&1 || { echo "The cluster is not reachable. Create it first (shelf up), and wait for the node to be Ready." >&2; exit 1; }
# Only this step's checks run, and each wait is capped at 30 s: the lab's own checks.yaml is replaced in a temporary copy of the labs folder.
LABS="${SHELF_LABS_DIR:-${SHELF_COURSE_DIR:-/root/course}/labs}"
T=$(mktemp -d) || { echo "Cannot make a temporary folder." >&2; exit 1; }
trap '[ -n "$T" ] && rm -rf "$T"' EXIT
for e in "$LABS"/*; do n=${e##*/}; [ "$n" = "$LAB" ] || ln -s "$e" "$T/$n"; done
cp -R "$LABS/$LAB" "$T/$LAB"
cat > "$T/$LAB/checks.yaml" <<'KILLERCODA_CHECKS'
apiVersion: labs.reconcile.example/v1
kind: LabChecks
lab: lab-m07-shelf-pod
checks:
  - id: pod-ready
    describe: The Pod shelf-api in the namespace shelf is Ready
    kubectl:
      - get
      - pod
      - shelf-api
      - -n
      - shelf
      - -o
      - json
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          jsonpath: '{.status.conditions[?(@.type=="Ready")].status}'
          equals: "True"
    hint: Run `kubectl get pod shelf-api --namespace shelf`. A Pod that shows Init:0/1 waits for an init container to start, and `kubectl describe pod shelf-api --namespace shelf` shows its events.
  - id: runs-the-api
    describe: A container of the Pod runs a Shelf api image
    kubectl:
      - get
      - pod
      - shelf-api
      - -n
      - shelf
      - -o
      - json
    expect:
      jsonpath: "{.spec.containers[*].image}"
      matches: "shelf/api:"
    hint: The regular container, in `containers`, runs `localhost:5001/shelf/api:v1`. The log shipper is not the api.
  - id: native-sidecar
    describe: An init container has restartPolicy Always, which makes it a native sidecar
    kubectl:
      - get
      - pod
      - shelf-api
      - -n
      - shelf
      - -o
      - json
    expect:
      jsonpath: '{.spec.initContainers[?(@.restartPolicy=="Always")].name}'
      matches: \S
    hint: "A sidecar is an entry under `initContainers`, not under `containers`, with `restartPolicy: Always`. Without that line it is an ordinary init container, which must finish before the api starts."
  - id: log-shipped
    describe: "The startup line is in the Pod's logs twice: once from the api and once from the sidecar's copy"
    kubectl:
      - logs
      - shelf-api
      - -n
      - shelf
      - --all-containers
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          regexCountAtLeast:
            pattern: '"msg":"shelf started"'
            count: 2
    hint: Both containers need the same emptyDir volume, mounted at the same path. The api writes its log to the file in SHELF_LOG_FILE as well as to stdout, and the sidecar follows that file. Compare `kubectl logs shelf-api --namespace shelf --container api` with the log of your sidecar.
KILLERCODA_CHECKS
out=$(SHELF_LABS_DIR="$T" timeout 60 "$SHELF" verify "$LAB" 2>&1); rc=$?
if [ "$rc" -eq 124 ]; then echo "The checks took too long. Wait a few seconds and click Check again." >&2; exit 1; fi
if [ "$rc" -ge 2 ]; then echo "$out" >&2; exit 1; fi
bad=0
for id in $CHECKS; do
  printf '%s\n' "$out" | grep -Eq "^(PASS|SKIP) $id " && continue
  bad=1; printf '%s\n' "$out" | grep -E -A2 "^FAIL $id "
done
[ "$bad" -eq 0 ] || echo "If you just applied a change, it may still be rolling out: wait a few seconds and click Check again." >&2
exit "$bad"
